import React, { useEffect, useMemo, useRef, useState, useSyncExternalStore } from 'react'
import { subscribePlan, getPlanSync } from '../lib/planSync.js'
import { SortTable } from '../components/SortTable.jsx'
import { loadWindow, subscribeWindow, getWindow, rowsFor, buckets, dayStats, conform, temp, runStartOf, refineStarts, refinedStart, drainSince, WINDOW_HOURS } from '../lib/window.js'
import { testType, ttSlot, resolveDay, STATUS, groupSerials, todayKey, dayKey, dayLong, dayLabel, timeOn, windowOn, cyclesOn, cycleAt, activeSerials, removedFrom, takeOut, putBack, TAKE_OUT_REASONS, takeOutReasons, loadDecls, loadRota } from '../lib/plan.js'
import { TEMP_WARN, TEMP_LIMIT } from '../lib/profile.js'
import { fmtDur } from '../lib/cycles.js'
import { median, pctl, hm, dt, ago, MIN, H } from '../lib/format.js'
import { online, status, lifetimeCycles } from '../lib/device.js'
import { fmtLifetime } from '../lib/fmt.js'
import { GROUP } from '../lib/fleet.js'
import { MultiLineChart, Sparkline, tooltipHtml } from '../components/charts.jsx'
import { Segmented, Stat } from '../components/Primitives.jsx'
import { buildStyleMap, keyBackground } from '../lib/palette.js'

// A battery end label that would sit on the 0% / 100% axis mark only repeats the axis.
const pctLabel = v => { const r = Math.round(v); return r >= 100 || r <= 0 ? null : `${r}%` }
const CSTATE = { conforming: ['pill-ok', 'On track'], drifting: ['pill-warn', 'Drifting'], silent: ['', 'Not reporting'], untyped: ['', 'No test declared'] }
const statusBadge = st => <span className={`pill ${{ declared: 'pill-run', confirmed: 'pill-ok', inferred: 'pill-warn', unclassified: '', none: '' }[st]}`}>{STATUS[st].label}</span>

export default function TodayView({ fleet }) {
  const { DEV, allCycles, opts } = fleet
  const win = useSyncExternalStore(subscribeWindow, getWindow, getWindow)
  useEffect(() => { loadWindow(DEV) }, [DEV])

  const now = Date.now()
  const [planRev, setPlanRev] = useState(0) // bumped after a take-out / put-back, to re-read the plan
  const planSync = useSyncExternalStore(subscribePlan, getPlanSync, getPlanSync) // shared plan changed elsewhere
  // The day whose run is on now. A run planned 10:00 → 04:00 belongs to the day it started,
  // so until yesterday's overnight window closes (and today's has not opened) Today stays
  // on yesterday's run.
  const dayFor = k => {
    const ran = allCycles.filter(c => dayKey(c.start) === k).length
    const r = resolveDay(k, { decls: DECLS(), rota: ROTA(), ran, devices: DEV.length })
    const src = r.decl || r.rota || null
    return { ...r, key: k, tt: testType(r.testType), src, ran, serials: groupSerials(src && src.group, DEV), ...windowOn(k, src) }
  }
  const T = useMemo(() => {
    // A day can hold several cycles. Show the one running now (including yesterday's still
    // going past midnight), else the next one to start today, else today's last one.
    const decls = DECLS(), todays = cyclesOn(decls, todayKey())
    const pick = cycleAt(decls, now) || todays.find(c => c.startMs > now) || todays[todays.length - 1] || null
    if (!pick) return dayFor(todayKey())
    const base = dayFor(pick.key), src = pick.decl
    return { ...base, testType: src.testType, tt: testType(src.testType), decl: src, src,
      // devices taken out of this cycle leave its charts and table from the moment they left
      serials: activeSerials(src, DEV, now), removed: removedFrom(src), startMs: pick.startMs, endMs: pick.endMs, overnight: pick.overnight,
      cycleNo: cyclesOn(decls, pick.key).findIndex(c => c.decl.id === src.id) + 1, cycleCount: cyclesOn(decls, pick.key).length }
  }, [DEV, allCycles, win.at2, todayKey(), planRev, planSync.v])
  const key = T.key
  const [takingOut, setTakingOut] = useState(null) // serial whose take-out form is open

  const winTo = Math.min(now, T.endMs)
  const conf = useMemo(() => T.serials.map(s => conform(s, T.tt, T.startMs, winTo)), [T, win.at2])
  const reporting = conf.filter(c => c.state !== 'silent')
  const conforming = conf.filter(c => c.state === 'conforming')
  const drifting = conf.filter(c => c.state === 'drifting')

  // Each device's own run: when it came off the charger and how fast it is draining. The
  // window opens when the plan says (07:00); the run starts when someone pulls the devices.
  const coarse = useMemo(() => conf.filter(c => c.rows?.length).map(c => ({ c,
    // from 2 h before the window, so a device pulled early (09:46 for a 10:00 window) is seen leaving the charger
    start: runStartOf(rowsFor(c.serial).filter(r => { const t = Date.parse(r.timestamp); return t >= T.startMs - 2 * H && t <= winTo })) })), [conf])
    // then pin each switch-off to the minute between the last reading on charge and the first off it
  const [refineRev, setRefineRev] = useState(0)
  useEffect(() => { let live = true
    refineStarts(coarse.map(x => ({ serial: x.c.serial, start: x.start }))).then(n => { if (live && n) setRefineRev(v => v + 1) })
    return () => { live = false } }, [coarse])
  const runs = useMemo(() => new Map(coarse.map(({ c, start: s0 }) => {
    const start = refinedStart(c.serial, s0) || s0
    return [c.serial, { start, rate: drainSince(c.rows, start), now: c.rows[c.rows.length - 1].battery_pct }]
  })), [coarse, refineRev])
  const all = [...runs.values()], started = all.filter(r => r.start)
  const runStart = started.length ? median(started.map(r => r.start.t)) : null
  const nows = all.map(r => r.now), medNow = nows.length ? median(nows) : null
  const rates = started.map(r => r.rate).filter(v => v != null && v > 0)
  const rate = rates.length ? median(rates) : null
  // The lab's daily run goes back on charge at 15–25%, so 20% is "the run is done".
  const END_BAND = 20
  const etaEnd = rate && medNow > END_BAND ? now + (medNow - END_BAND) / rate * H : null
  const etaEmpty = rate && medNow > 0 ? now + medNow / rate * H : null
  const when = t => (dayKey(t) === key ? hm(t) : dt(t))
  // Start the charts half an hour before the run so the drop-off is visible, not four
  // hours of a flat line at 100% while the devices sat on the charger.
  const chartFrom = runStart ? Math.max(T.startMs, runStart - 30 * MIN) : T.startMs


  // Which devices the two charts show. null = every device (the default); a Set narrows
  // both charts at once. Colours come from the full sorted list, so a device keeps its
  // colour whatever else is ticked — the same rule T7's own device picker follows.
  const [picked, setPicked] = useState(null)
  const sorted = useMemo(() => [...T.serials].sort(), [T.serials.join(',')])
  const styleOf = useMemo(() => buildStyleMap(sorted), [sorted])
  const colorOf = useMemo(() => new Map([...styleOf].map(([k, v]) => [k, v.color])), [styleOf])
  const isOn = sn => picked == null || picked.has(sn)
  const toggle = sn => setPicked(p => {
    const n = new Set(p ?? sorted); n.has(sn) ? n.delete(sn) : n.add(sn)
    return n.size === sorted.length ? null : n
  })
  // Search narrows the charts and the table to matching serials ("044" finds …00044).
  const [query, setQuery] = useState('')
  const q = query.trim().toLowerCase()
  const matches = sn => !q || sn.toLowerCase().includes(q)
  const [listOpen, setListOpen] = useState(false)
  const [listQ, setListQ] = useState('') // search inside the Devices today list
  const listShown = listOpen || !!q
  // A device clicked in the table is ticked alone in the two charts above (Every device),
  // and the page scrolls up to them; clicking it again ticks every device again.
  const chartsRef = useRef(null)
  const shown = conf.filter(c => c.rows?.length && isOn(c.serial) && matches(c.serial))
  const few = shown.length <= 4 // few enough to label every line by name

  const lastOf = c => c.rows[c.rows.length - 1].battery_pct
  const lo = shown.length ? shown.reduce((a, b) => lastOf(b) < lastOf(a) ? b : a) : null
  const hi = shown.length ? shown.reduce((a, b) => lastOf(b) > lastOf(a) ? b : a) : null
  const ptsOf = (c, pick = r => r.battery_pct) => c.rows.filter(r => Date.parse(r.timestamp) >= chartFrom && pick(r) != null)
    .map(r => ({ x: Date.parse(r.timestamp), y: pick(r) }))
  // Each chart can show every ticked device or their average. Battery opens on every
  // device (spot the outlier); temperature on the average (the fleet trend), as before.
  const [battMode, setBattMode] = useState('all')
  const [tempMode, setTempMode] = useState('avg')
  const MODES = [{ id: 'all', label: 'Every device' }, { id: 'avg', label: 'Average' }]
  const only = picked != null && picked.size === 1 ? [...picked][0] : null
  const focusDevice = sn => {
    if (only === sn) { setPicked(null); return }
    setPicked(new Set([sn])); setBattMode('all'); setTempMode('all')
    chartsRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' })
  }
  const selSerials = shown.map(c => c.serial)
  const avg = a => a.reduce((x, y) => x + y, 0) / a.length
  const battAvg = useMemo(() => buckets(selSerials, chartFrom, winTo, r => r.battery_pct, avg), [selSerials.join(','), chartFrom, win.at2])
  const battMin = useMemo(() => buckets(selSerials, chartFrom, winTo, r => r.battery_pct, a => Math.min(...a)), [selSerials.join(','), chartFrom, win.at2])
  const battMax = useMemo(() => buckets(selSerials, chartFrom, winTo, r => r.battery_pct, a => Math.max(...a)), [selSerials.join(','), chartFrom, win.at2])
  const tAvg = useMemo(() => buckets(selSerials, chartFrom, winTo, temp, avg), [selSerials.join(','), chartFrom, win.at2])

  // The projection starts from the line actually drawn: the average in Average mode, the
  // median of the ticked devices otherwise, at their median drain rate.
  const selRuns = shown.map(c => runs.get(c.serial)).filter(Boolean)
  const selRates = selRuns.filter(r => r.start && r.rate > 0).map(r => r.rate)
  const selRate = selRates.length ? median(selRates) : null
  const selNow = battMode === 'avg' ? (battAvg.length ? battAvg[battAvg.length - 1].y : null)
    : (selRuns.length ? median(selRuns.map(r => r.now)) : null)
  const selEmpty = selRate && selNow > 0 ? now + selNow / selRate * H : null
  // no drain to project when every shown device is back on the charger
  const allCharging = shown.length > 0 && shown.every(c => fleet.DMAP.get(c.serial)?.snap?.charging)
  const projTo = selRate && selNow != null && T.endMs > now && !allCharging ? Math.min(T.endMs, selEmpty || T.endMs) : null
  const projection = projTo ? [{ x: now, y: selNow }, { x: projTo, y: Math.max(0, selNow - selRate * (projTo - now) / H) }] : []
  const projSeries = projection.length ? [{ id: 'projected', label: 'Projected', pts: projection, color: 'var(--text-3)', width: 1.6, dash: '2 4', smooth: false, endLabel: `${Math.round(projection[1].y)}%`, labelColor: 'var(--text-3)' }] : []
  const tail = sn => '…' + sn.slice(-5)

  const series = battMode === 'avg'
    ? [
        { id: 'max', label: 'Highest', pts: battMax, color: 'var(--series-8)', width: 1.25, opacity: .8, dash: '3 3', endLabel: battMax.length ? pctLabel(battMax[battMax.length - 1].y) : null, labelColor: 'var(--series-8)' },
        { id: 'min', label: 'Lowest', pts: battMin, color: 'var(--series-3)', width: 1.25, opacity: .8, dash: '3 3', endLabel: battMin.length ? pctLabel(battMin[battMin.length - 1].y) : null, labelColor: 'var(--series-3)' },
        { id: 'avg', label: 'Average', pts: battAvg, color: 'var(--series-1)', width: 2.4, endLabel: battAvg.length ? pctLabel(battAvg[battAvg.length - 1].y) : null },
      ]
    : [
        ...shown.map(c => {
          const drift = c.state === 'drifting'
          return { id: c.serial, label: tail(c.serial) + (drift ? ' · drifting' : ''), pts: ptsOf(c), color: colorOf.get(c.serial), width: drift ? 2.8 : 1.5, opacity: few || drift ? 1 : .8,
            dash: styleOf.get(c.serial)?.dash,
            endLabel: few ? `${c.serial.slice(-4)} ${lastOf(c)}%` : (c === lo || c === hi) ? pctLabel(lastOf(c)) : null }
        }),
      ]
  const tempSeries = tempMode === 'avg'
    ? [
        { id: 'avg', label: 'Average', pts: tAvg, color: 'var(--series-1)', width: 2, endLabel: tAvg.length ? `avg ${tAvg[tAvg.length - 1].y.toFixed(0)}°` : null },
      ]
    : shown.map(c => {
        const pts = ptsOf(c, temp), last = pts[pts.length - 1]
        return { id: c.serial, label: tail(c.serial), pts, color: colorOf.get(c.serial), dash: styleOf.get(c.serial)?.dash, width: 1.6,
          endLabel: last && (few || last.y >= TEMP_WARN) ? `${c.serial.slice(-4)} ${last.y.toFixed(0)}°` : null }
      })
  // Tooltip rows in T7's style; the busiest charts list the six most relevant lines.
  const battTip = (t, hits) => {
    const rows = hits.filter(h => h.p).sort((a, b) => a.p.y - b.p.y)
    const top = rows.length > 6 ? [...rows.slice(0, 3), ...rows.slice(-3)] : rows
    return tooltipHtml(hm(t), top.map(({ s, p }) => ({ color: s.color, name: s.label || s.id, value: `${Math.round(p.y)}%` })))
      + (rows.length > 6 ? `<div class="tt-time" style="margin:4px 0 0">+${rows.length - 6} more between</div>` : '')
  }
  const tempTip = (t, hits) => {
    const rows = hits.filter(h => h.p).sort((a, b) => b.p.y - a.p.y)
    return tooltipHtml(hm(t), rows.slice(0, 6).map(({ s, p }) => ({ color: s.color, name: s.label || s.id, value: `${p.y.toFixed(1)} °C` })))
      + (rows.length > 6 ? `<div class="tt-time" style="margin:4px 0 0">+${rows.length - 6} more, all cooler</div>` : '')
  }
  const picker = <DevicePicker serials={sorted} picked={picked} colorOf={colorOf} styleOf={styleOf} drifting={new Set(drifting.map(d => d.serial))}
    onToggle={toggle} onAll={() => setPicked(null)} onNone={() => setPicked(new Set())}
    onSet={set => setPicked(set.size === sorted.length ? null : set)} />
  const noneTicked = picked != null && picked.size === 0
  const silent = T.serials.length - reporting.length

  return (
    <div className="view-stack">
      <div className="card" style={{ borderLeft: `3px solid ${T.tt ? `var(--tt-${ttSlot(T.tt.id)})` : 'var(--border-strong)'}` }}>
        <div className="card-body today-head">
        <div className="today-head-main">
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap', fontSize: 11.5, letterSpacing: '.04em', color: 'var(--text-3)', fontWeight: 600 }}>
            {dayLong(key)} {statusBadge(T.status)}
            <span className={`pill ${reporting.length ? 'pill-run pill-live' : ''}`}>Live · {reporting.length} device{reporting.length === 1 ? '' : 's'} reporting</span>
          </div>
          <h1 style={{ margin: '6px 0 4px', fontSize: 26, lineHeight: 1.15 }}>{T.tt ? T.tt.name : 'No test set'}{T.cycleCount > 1 ? <span className="secondary" style={{ fontSize: 14, fontWeight: 500 }}> · cycle {T.cycleNo} of {T.cycleCount}</span> : null}</h1>
          <div className="secondary" style={{ fontSize: 12.5 }}>
            {T.tt ? <>{T.source === 'rota' ? 'From the standing weekly rota' : <>Planned{T.src?.by ? <> by <b>{T.src.by}</b></> : null}{T.src?.at ? ` at ${hm(T.src.at)}` : ''}</>}
              {' '}· {T.serials.length} devices · window {hm(T.startMs)}–{hm(T.endMs)}{T.overnight ? ' next day' : ''}</>
              : <>The MDM can't tell which test is running. <a className="link" href="#/nx/plan">Set one on the Cycle plan</a>.</>}
          </div>
        </div>
        </div>
      </div>

      <div className="stat-row">
        {/* how long the devices have been running since they came off the charger, and how
            much of the planned cycle is left (to its end time on the Cycle plan) */}
        <Metric label="Running for"
          value={runStart ? <>{fmtDur(now - runStart)}{T.endMs > now
            ? <span className="secondary" style={{ fontSize: 13 }}> · {fmtDur(T.endMs - now)} left</span>
            : <span className="secondary" style={{ fontSize: 13 }}> · planned end passed</span>}</> : 'Not started'}
          delta={runStart ? `off charger ${hm(runStart)} · planned ${hm(T.startMs)} → ${hm(T.endMs)}${T.overnight ? ' next day' : ''}`
            : `${started.length} of ${all.length} devices off charger · planned ${hm(T.startMs)} → ${hm(T.endMs)}${T.overnight ? ' next day' : ''}`} />
        <Metric label="Battery now" value={medNow != null ? `${medNow}%` : '—'}
          delta={nows.length ? `median · range ${Math.min(...nows)}–${Math.max(...nows)}%` : 'no readings yet'} />
        <Metric label="Drain rate" value={rate ? <>{rate.toFixed(2)}<span className="secondary" style={{ fontSize: 13 }}> %/h</span></> : '—'}
          delta={rate ? `${(rate / 6).toFixed(2)}% per 10 min · median of ${rates.length}` : 'needs 20 min of running'} />
        <Metric label={`Reaches ${END_BAND}%`} value={etaEnd ? <>{hm(etaEnd)}{dayKey(etaEnd) !== key && <span className="secondary" style={{ fontSize: 13, fontWeight: 500 }}> {new Date(etaEnd).toLocaleDateString([], { month: 'short', day: 'numeric' })}</span>}</> : medNow != null && medNow <= END_BAND ? 'Done' : '—'}
          delta={etaEnd ? `${fmtDur(etaEnd - now)} from now${etaEmpty ? ` · empty ≈ ${when(etaEmpty)}` : ''}` : medNow != null && medNow <= END_BAND ? 'median is in the end band' : 'at the current rate'} />
        <Metric label="On track with plan" color={T.tt && conforming.length === T.serials.length ? 'var(--ok)' : drifting.length ? 'var(--warn)' : null}
          value={<>{conforming.length}<span className="secondary" style={{ fontSize: 13 }}> / {T.serials.length}</span></>}
          delta={!T.tt ? 'nothing declared to match' : drifting.length || silent
            ? [drifting.length && `${drifting.length} drifting`, silent && `${silent} not reporting`].filter(Boolean).join(' · ')
            : 'every device matches the declared test'} />
        {/* wireless charging: devices whose pad is active now (a load placed on it), from the
            latest check-in; the drop-down lists every device, active ones first and highlighted */}
        {(() => {
          // the cycle's devices only: one taken out of it leaves this count too
      const inCycle = new Set(T.serials)
      const rows = (T.serials.length ? DEV.filter(d => inCycle.has(d.serial)) : DEV).map(d => {
            const e = typeof d.snap?.extra === 'string' ? (() => { try { return JSON.parse(d.snap.extra) } catch (x) { return {} } })() : (d.snap?.extra || {})
            // wlc_status 1/2 = a load placed and being charged (seen during WLC on Load);
            // wlc_charging alone = the pad switched on, nothing on it
            const on = e.wlc_status != null && +e.wlc_status !== 0, padOn = e.wlc_charging === true
            return { d, on, padOn, live: online(d) }
          }).sort((a, b) => (b.on - a.on) || (b.padOn - a.padOn) || (a.d.serial < b.d.serial ? -1 : 1))
          const n = rows.filter(r => r.on).length
          return <Stat label="WLC · load placed" value={<>{n}<span className="secondary" style={{ fontSize: 13 }}> / {rows.length}</span></>}
            foot={`load placed on the pad · ${rows.filter(r => r.padOn && !r.on).length} more with the pad on, no load`}
            breakdownLabel="WLC pad, every device (latest check-in)" breakdownRight breakdownWide
            breakdown={rows.map(r => ({ id: r.d.serial, label: r.d.serial, value: r.on ? 1 : 0, highlight: r.on,
              display: r.on ? 'Load placed' : r.padOn ? 'Pad on, no load' : 'Off', hint: r.live ? undefined : '· offline', onClick: () => focusDevice(r.d.serial) }))} />
        })()}
      </div>






      {!win.at ? <Stale win={win} n={DEV.length} /> : <>
        {/* after picking devices (a click in the list, or the Devices picker), one click back to all */}
        {picked != null && (
          <div className="pick-bar">
            <span>{picked.size === 0 ? 'No devices ticked'
              : picked.size <= 3 ? <>Showing only <b className="mono">{[...picked].join(', ')}</b></>
              : <>Showing <b>{picked.size}</b> of {sorted.length} devices</>}</span>
            <button type="button" className="btn btn-sm" onClick={() => setPicked(null)}>× Clear selection</button>
          </div>
        )}
        {/* battery and temperature side by side; stacked again on narrow screens (.grid-2) */}
        <div className="grid grid-2" ref={chartsRef} style={{ scrollMarginTop: 80 }}>
        <div className="card">
          <div className="card-head"><div><h2>T7 battery, today</h2><div className="card-sub">from {hm(chartFrom)} · live from MDM · every check-in</div></div>
            <Segmented ariaLabel="Battery chart" options={MODES} value={battMode} onChange={setBattMode} /></div>
          <div className="card-body">
            {picker}
            {/* what each line is, with swatches that match the lines drawn */}
            <div className="legend" style={{ margin: '8px 0 10px' }}>
              {battMode === 'avg' ? <>
                <span className="legend-item"><i className="legend-key-line" style={{ background: 'var(--series-1)' }} />Average battery of {shown.length} device{shown.length === 1 ? '' : 's'}</span>
                <span className="legend-item"><i className="legend-key-line" style={{ background: keyBackground('var(--series-8)', '3 3') }} />Highest device</span>
                <span className="legend-item"><i className="legend-key-line" style={{ background: keyBackground('var(--series-3)', '3 3') }} />Lowest device</span>
              </> : <>
                {drifting.length ? <span className="legend-item"><i className="legend-key-line" style={{ background: 'var(--status-warning)', height: 3 }} />Thicker line = not following the planned test</span> : null}
              </>}
            </div>
            {noneTicked ? <div className="empty">No devices ticked — pick some above, or choose Select all.</div> :
            <MultiLineChart series={series} h={230} yMax={100} yFmt={v => v + '%'} xFmt={hm} x0={chartFrom} x1={winTo}
              tip={battTip} />}
          </div>
        </div>
        <div className="card">
          <div className="card-head"><div><h2>Battery temperature, today</h2><div className="card-sub">{shown.length} device{shown.length === 1 ? '' : 's'} · °C</div></div>
            <Segmented ariaLabel="Temperature chart" options={MODES} value={tempMode} onChange={setTempMode} /></div>
          <div className="card-body">
            {picker}
            <div className="legend" style={{ margin: '8px 0 10px' }}>
              {tempMode === 'avg' ? <>
                <span className="legend-item"><i className="legend-key-line" style={{ background: 'var(--series-1)' }} />Average temperature of {shown.length} device{shown.length === 1 ? '' : 's'}</span>
              </> : <span className="legend-item secondary">One line per device — each colour matches that device in the Devices list above. {few ? 'Each line ends with its device and temperature now.' : `The numbers at the right end mark devices at ${TEMP_WARN} °C or hotter now.`}</span>}
            </div>
            {noneTicked ? <div className="empty">No devices ticked — pick some above, or choose Select all.</div> :
            <MultiLineChart h={230} yMax={60} yFmt={v => v.toFixed(0) + '°'} xFmt={hm} x0={chartFrom} x1={winTo}
              series={tempSeries}
              tip={tempTip} />}
          </div>
        </div>
        </div>
        <div className="card">
          {/* closed by default; a search opens it, since the search is about these rows */}
          <div className="card-head" role="button" tabIndex={0} aria-expanded={listShown} style={{ cursor: 'pointer' }}
            onClick={() => setListOpen(o => !o)} onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setListOpen(o => !o) } }}>
            <h2><span aria-hidden="true" style={{ display: 'inline-block', width: 16 }}>{listShown ? '▾' : '▸'}</span>Devices today ({conf.filter(c => matches(c.serial)).length})</h2>
            {/* the list's search sits in its title row, only while the list is open */}
            {listShown
              ? <span style={{ display: 'flex', alignItems: 'center', gap: 10 }} onClick={e => e.stopPropagation()} onKeyDown={e => e.stopPropagation()}>
                  <input className="control" type="search" placeholder="Search this list… (e.g. 044)" value={listQ} onChange={e => setListQ(e.target.value)} style={{ width: 240 }} aria-label="Search the device list" />
                  <span className="secondary">{reporting.length} reporting</span>
                </span>
              : <span className="secondary">{reporting.length} reporting · click to show every device — click one to chart it alone</span>}
          </div>
          {listShown && <div className="scroll-x"><SortTable head={[{ label: 'Device' }, { label: 'Against plan' }, { label: 'Battery', className: 'r' }, { label: 'Off charger', className: 'r' },
              { label: 'Drain', className: 'r' }, { label: 'Lifetime cycles (MDM)', className: 'r' }, { label: 'Temp now', className: 'r' },
              { label: 'Peak today', className: 'r' }, { label: `≥${TEMP_LIMIT} °C`, className: 'r' }, { label: 'Today', className: 'r', sortable: false },
              ...(T.decl ? [{ label: '', sortable: false }] : [])]}>
              {conf.filter(c => matches(c.serial) && c.serial.toLowerCase().includes(listQ.trim().toLowerCase())).sort((a, b) => ((b.state === 'drifting') - (a.state === 'drifting')) || ((fleet.DMAP.get(a.serial)?.snap?.battery_pct ?? 999) - (fleet.DMAP.get(b.serial)?.snap?.battery_pct ?? 999))).map(c => {
                const r = runs.get(c.serial)
                const d = fleet.DMAP.get(c.serial); if (!d) return null
                const st = status(d), s = dayStats(c.serial, T.startMs), cs = CSTATE[c.state]
                const row = <tr key={c.serial} className={`row-link${only === c.serial ? ' is-selected' : ''}`} onClick={() => focusDevice(c.serial)}
                  title={only === c.serial ? 'Click to show every device again' : `Show only ${c.serial} in the charts above`}>
                  <td className="mono"><button type="button" className="link-btn plain-link mono" onClick={e => { e.stopPropagation(); focusDevice(c.serial) }}>{c.serial}</button></td>
                  <td><span className={`pill ${cs[0]}`}>{cs[1]}</span></td>
                  <td className="r">{st.pct != null ? <span className="batt num">{st.pct}%<span className={`bar ${st.pct < 20 ? 'warn' : st.k === 'ready' ? 'ok' : 'run'}`}><i style={{ width: `${st.pct}%` }} /></span></span> : <span className="secondary">—</span>}</td>
                  <td className="r mono" title={r?.start?.firstOff ? `last check-in on charge ${new Date(r.start.after).toLocaleTimeString()} · first off charge ${new Date(r.start.firstOff).toLocaleTimeString()} — the MDM has no reading in between` : undefined}>
                    {r?.start ? hm(r.start.t) : <span className="secondary">still full</span>}
                    {r?.start?.firstOff && r.start.firstOff - r.start.t > 5 * MIN ? <span className="secondary" style={{ fontSize: 11 }}> – {hm(r.start.firstOff)}</span> : null}</td>
                  <td className="r mono" style={{ color: c.state === 'drifting' ? 'var(--warn)' : 'inherit' }}>{r?.rate != null ? r.rate.toFixed(2) + ' %/h' : <span className="secondary">—</span>}</td>
                  <td className="r mono">{fmtLifetime(lifetimeCycles(d.snap))}</td>
                  <td className="r mono" style={{ color: online(d) && d.snap.battery_temp_c >= TEMP_LIMIT ? 'var(--bad)' : online(d) && d.snap.battery_temp_c >= TEMP_WARN ? 'var(--warn)' : 'inherit' }}>{online(d) && d.snap.battery_temp_c ? d.snap.battery_temp_c.toFixed(1) + ' °C' : <span className="secondary">—</span>}</td>
                  <td className="r mono" style={{ color: s?.maxTemp >= TEMP_LIMIT ? 'var(--bad)' : s?.maxTemp >= TEMP_WARN ? 'var(--warn)' : 'inherit' }}>{s?.maxTemp != null ? s.maxTemp.toFixed(1) + ' °C' : <span className="secondary">—</span>}</td>
                  <td className="r mono" style={{ color: s?.minAbove45 ? 'var(--bad)' : 'inherit' }}>{s?.minAbove45 ? fmtDur(s.minAbove45 * MIN) : <span className="secondary">—</span>}</td>
                  <td className="r">{s ? <Sparkline vals={s.battPts.map(p => p.y)} /> : <span className="secondary">—</span>}</td>
                  {T.decl && <td className="r"><button type="button" className="btn btn-sm" title={`Take ${c.serial} out of this cycle, with a reason`}
                    onClick={e => { e.stopPropagation(); setTakingOut(t => t === c.serial ? null : c.serial) }}>{takingOut === c.serial ? 'Cancel' : 'Take out'}</button></td>}
                </tr>
                // the take-out form opens right under its device, as part of the table
                return takingOut === c.serial && T.decl ? [row,
                  <tr key={c.serial + ':out'} data-attached="1" className="takeout-row"><td colSpan={11}>
                    <TakeOutForm serial={c.serial} cycle={T} onCancel={() => setTakingOut(null)}
                      onSave={rec => { takeOut(GROUP, T.decl.id, { serial: c.serial, ...rec }); setTakingOut(null); setPlanRev(v => v + 1) }} />
                  </td></tr>] : row
              })}
          </SortTable></div>}
        </div>
        {T.decl && T.removed?.length > 0 && (
          <div className="card">
            <div className="card-head"><h2>Taken out of this cycle ({T.removed.length})</h2><span className="secondary">kept on record · their cycles from then on don't count toward {T.tt?.name}</span></div>
            <div className="scroll-x"><SortTable head={[{ label: 'Device' }, { label: 'Taken out' }, { label: 'Reason' }, { label: 'Note' }, { label: 'By' }, { label: '', sortable: false }]}>
              {T.removed.map(r => (
                <tr key={r.serial}>
                  <td className="mono">{r.serial}</td>
                  <td className="mono">{dayKey(r.at) === todayKey() ? hm(r.at) : dt(r.at)}</td>
                  <td>{r.reason}</td>
                  <td>{r.note || <span className="secondary">—</span>}</td>
                  <td>{r.by || <span className="secondary">—</span>}</td>
                  <td className="r"><button type="button" className="btn btn-sm" onClick={() => { if (confirm(`Put ${r.serial} back into this cycle? The record of it being taken out is removed.`)) { putBack(GROUP, T.decl.id, r.serial); setPlanRev(v => v + 1) } }}>Put back</button></td>
                </tr>
              ))}
            </SortTable></div>
          </div>
        )}
      </>}
    </div>
  )
}

// plan.js stores per cycles-group; these keep the group name in one place.
const DECLS = () => loadDecls(GROUP)
const ROTA = () => loadRota(GROUP)

const Metric = ({ label, value, delta, color }) => (
  <div className="stat">
    <div className="stat-label">{label}</div>
    <div className="stat-value" style={color ? { color } : undefined}>{value}</div>
    <div className="stat-foot">{delta}</div>
  </div>
)
const Stale = ({ win, n }) => (
  <div className="banner">
    <svg viewBox="0 0 16 16" width="16" height="16" style={{ flex: "none", marginTop: 2 }} aria-hidden="true" fill="none" stroke="currentColor" strokeWidth="1.5"><circle cx="8" cy="8" r="6.5" /><path d="M8 7v4M8 5h.01" /></svg>
    <div>{win.loading ? <><span className="spin" /> Reading the last {WINDOW_HOURS} h of history for {n} devices…</> : win.err ? `Could not read recent history: ${win.err}` : 'No recent history loaded yet.'}</div>
  </div>
)
function DeviceDay({ d, from }) {
  const s = dayStats(d.serial, from), st = status(d)
  return <>
    <h3 className="mono">{d.serial}</h3>
    <div className="sub">{(d.snap?.device_class || 'device').toUpperCase()} · {st.label} · seen {ago(Date.parse(d.snap.last_seen_at))}</div>
    <div className="big num">{st.pct != null ? st.pct + '%' : '—'}<small>{online(d) && d.snap.battery_temp_c ? d.snap.battery_temp_c.toFixed(1) + ' °C now' : st.label.toLowerCase()}</small></div>
    {!s ? <div className="empty-note">No readings in this window.</div> : <>
      <hr /><h4>Today</h4>
      <dl className="kv">
        <dt>At window start</dt><dd className="mono">{s.startPct}%</dd>
        <dt>Drained</dt><dd className="mono">{s.drained.toFixed(0)}%</dd>
        <dt>Peak temperature</dt><dd className="mono" style={{ color: s.maxTemp >= TEMP_LIMIT ? 'var(--bad)' : s.maxTemp >= TEMP_WARN ? 'var(--warn)' : 'inherit' }}>{s.maxTemp != null ? s.maxTemp.toFixed(1) + ' °C' : '—'}</dd>
        <dt>Average temperature</dt><dd className="mono">{s.avgTemp != null ? s.avgTemp.toFixed(1) + ' °C' : '—'}</dd>
        <dt>Over {TEMP_LIMIT} °C</dt><dd className="mono" style={{ color: s.minAbove45 ? 'var(--bad)' : 'inherit' }}>{s.minAbove45 ? fmtDur(s.minAbove45 * MIN) : '—'}</dd>
        <dt>Samples</dt><dd className="mono">{s.n}</dd>
      </dl>
    </>}
  </>
}
// Devices whose readings since the cycle started don't look like the planned test: a
// discharge test wants the battery down at least 3 points and off the charger, a charging
// test the battery up 3 or on charge (window.js conform). Each row says which part failed.
function Drifters({ drifting, tt }) {
  const why = c => {
    if (tt?.expect === 'charge') return `battery ${c.delta >= 0 ? 'up' : 'down'} only ${Math.abs(c.delta)}% and not charging`
    if (c.charging) return c.delta <= -3 ? `on the charger now (battery ${c.delta}%)` : `on the charger — battery ${c.delta > 0 ? '+' : ''}${c.delta}% since the start`
    return c.delta > 0 ? `battery went up ${c.delta}% — expected it to drain` : `battery moved only ${c.delta}% — expected at least a 3% drop`
  }
  return (
    <div className="card">
      <div className="card-head"><h3>Drifting — not behaving like {tt ? tt.name : 'the planned test'}</h3><span className="card-sub">{drifting.length} device{drifting.length === 1 ? '' : 's'}</span></div>
      {drifting.length ? <>
        {drifting.map(c => (
          <div className="row-item" key={c.serial}>
            <span className="mono">{c.serial}</span>
            <span className="grow secondary" style={{ fontSize: 12.5 }}>{why(c)}</span>
            <span className="mono" style={{ color: 'var(--status-warning)' }}>{(c.delta > 0 ? '+' : '') + c.delta}%</span>
          </div>
        ))}
        <div className="card-body"><div className="help">Checked from the cycle's start: a {tt?.expect === 'charge' ? 'charging test expects the battery to rise at least 3% or the device to be charging' : 'discharge test expects the battery to drop at least 3% with the device off the charger'}. Often it just means the device hasn't been taken off (or put on) charge yet. If it has been taken away, use Take out in the device list.</div></div>
      </> : <div className="empty">{tt ? 'Every reporting device matches the planned test.' : 'Nothing planned for today, so nothing can drift.'}</div>}
    </div>
  )
}

// T7's own device picker markup (chart-legend-details / series-legend), so it looks and
// behaves like the one on the Overview's single-test view. Drifting devices are marked.
function DevicePicker({ serials, picked, colorOf, styleOf, drifting, onToggle, onAll, onNone, onSet }) {
  const n = picked == null ? serials.length : picked.size
  const [q, setQ] = useState('')
  const shown = serials.filter(sn => sn.toLowerCase().includes(q.trim().toLowerCase()))
  const ticked = new Set(picked ?? serials)
  // with a search typed, Select all / Clear all act on the serials it shows
  const selectShown = () => q.trim() ? onSet(new Set([...ticked, ...shown])) : onAll()
  const clearShown = () => { if (!q.trim()) return onNone(); const n2 = new Set(ticked); shown.forEach(sn => n2.delete(sn)); onSet(n2) }
  return (
    <details className="chart-legend-details">
      <summary>Devices ({n}/{serials.length})</summary>
      <div className="series-legend-actions">
        <input className="control" type="search" placeholder="Search serials… (e.g. 044)" value={q} onChange={e => setQ(e.target.value)} style={{ flex: '1 1 200px', maxWidth: 280 }} />
        <button type="button" className="btn" onClick={selectShown}>Select all</button>
        <button type="button" className="btn" onClick={clearShown}>Clear all</button>
      </div>
      <div className="legend series-legend" role="group" aria-label="Devices to show on the charts">
        {shown.length ? shown.map(sn => (
          <label className="series-legend-item" key={sn}>
            <input type="checkbox" checked={picked == null || picked.has(sn)} onChange={() => onToggle(sn)} />
            <span className="legend-key-line" style={{ background: keyBackground(colorOf.get(sn), styleOf.get(sn)?.dash) }} aria-hidden="true" />
            <span>{sn}{drifting.has(sn) ? <span className="secondary"> · drifting</span> : null}</span>
          </label>
        )) : <span className="secondary">No serial matches “{q.trim()}”.</span>}
      </div>
    </details>
  )
}


// Taking one device out of the running cycle: a reason from a short list, an optional
// note and name. Saved on the cycle with the time, so the record says who left and why. A
// reason typed under "Other" is saved as that reason, and offered in the list from then on.
function TakeOutForm({ serial, cycle, onSave, onCancel }) {
  const reasons = useMemo(() => takeOutReasons(DECLS()), [])
  const [reason, setReason] = useState(reasons[0])
  const [note, setNote] = useState('')
  const [by, setBy] = useState(() => { try { return localStorage.getItem('declaredBy') || '' } catch (e) { return '' } })
  const needNote = reason === 'Other' && !note.trim()
  return (
    <div className="card-body takeout">
      <div style={{ marginBottom: 8 }}><b>Take <span className="mono">{serial}</span> out of {cycle.tt?.name}</b>
        <div className="secondary" style={{ fontSize: 12 }}>It leaves the charts and the cycle from now ({hm(Date.now())}). The run it is on stops counting toward this test.</div></div>
      <div className="takeout-grid">
        <label className="field"><span>Reason</span>
          <span className="ver" style={{ display: 'block' }}><select value={reason} onChange={e => setReason(e.target.value)} style={{ width: '100%' }}>
            {reasons.map(r => <option key={r}>{r}</option>)}</select></span></label>
        <label className="field"><span>{reason === 'Other' ? 'Reason (required, kept for next time)' : 'Note (optional)'}</span>
          <input className="input" value={note} onChange={e => setNote(e.target.value)} placeholder={reason === 'Other' ? 'e.g. testing v2.1.031' : 'e.g. taken by Sam for the customer demo'} /></label>
        <label className="field"><span>Taken out by</span>
          <input className="input" value={by} onChange={e => setBy(e.target.value)} placeholder="optional" /></label>
      </div>
      <div className="form-actions">
        <button className="btn" onClick={onCancel}>Cancel</button>
        <button className="btn btn-primary" disabled={needNote} title={needNote ? 'Add a note for "Other"' : undefined}
          onClick={() => { try { localStorage.setItem('declaredBy', by) } catch (e) {} onSave(reason === 'Other' ? { reason: note.trim(), note: '', by: by.trim() } : { reason, note: note.trim(), by: by.trim() }) }}>Take out</button>
      </div>
    </div>
  )
}
